#!/usr/bin/env python3
"""Simulate a bash shell hook driving `direnv export bash`."""
import subprocess, sys, os, re, base64, zlib, json, shlex

D = "/workspace/executable"
PROBE = "/tmp/probe/loading-lifecycle"
BASE = {"HOME": PROBE+"/home", "PATH": "/usr/bin:/bin", "TERM": "xterm"}

def dec(v):
    v=v.strip(); raw=base64.urlsafe_b64decode(v+'='*(-len(v)%4))
    return json.loads(zlib.decompress(raw))

def unesc(s):
    # bash $'...' unescape (minimal)
    return s.encode().decode('unicode_escape')

def apply(env, out):
    """Apply bash statements to env dict. Returns list of (op,name)."""
    ops=[]
    # split on ';' at top level is unsafe; use regex over known forms
    for m in re.finditer(r"(?:export ([A-Za-z_][A-Za-z0-9_]*)=\$'((?:[^'\\]|\\.)*)'|export ([A-Za-z_][A-Za-z0-9_]*)=([^;]*)|unset ([A-Za-z_][A-Za-z0-9_]*));", out):
        if m.group(1):
            env[m.group(1)] = unesc(m.group(2)); ops.append(('export',m.group(1)))
        elif m.group(3):
            env[m.group(3)] = m.group(4); ops.append(('export',m.group(3)))
        else:
            env.pop(m.group(5), None); ops.append(('unset',m.group(5)))
    return ops

def run(env, cwd, args=("export","bash"), extra=None):
    e = dict(env)
    if extra: e.update(extra)
    p = subprocess.run([D]+list(args), cwd=cwd, env=e, capture_output=True, text=True)
    return p

def show(p, label=""):
    print(f"--- {label} exit={p.returncode}")
    if p.stderr: print("STDERR:"); print(p.stderr, end="")
    if p.stdout: print("STDOUT:"); print(p.stdout)

def state(env):
    out=[]
    for k in ("DIRENV_DIR","DIRENV_FILE"):
        if k in env: out.append(f"  {k}={env[k]}")
    if "DIRENV_WATCHES" in env:
        out.append("  DIRENV_WATCHES="+json.dumps(dec(env["DIRENV_WATCHES"])))
    if "DIRENV_DIFF" in env:
        d=dec(env["DIRENV_DIFF"])
        out.append("  DIRENV_DIFF.p keys="+str(sorted(d['p'].keys())))
        out.append("  DIRENV_DIFF.n keys="+str(sorted(d['n'].keys())))
    return "\n".join(out) if out else "  (no DIRENV_* in env)"
